from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output

from taf.rfrl.procedures.resources.python.status_check.rmod.oran.oran_cpri_rmod import OranCpriRmod
from taf.rfrl.procedures.resources.python.status_check.rmod.oran.oran_ecpri_rmod import OranEcpriRmod
from taf.rfrl.procedures.resources.python.status_check.rmod.oran.oran_obsai_rmod import OranObsaiRmod


class OranRmodFactory:
    """
    Creates OranCpriRmod, OranEcpriRmod or OranObsaiRmod instances depending on rmod_link_protocol
    """

    @staticmethod
    @log_input_and_output
    def create_oran_rmod(rmod_link_protocol):
        """
        Creates ORAN Rmod instance
        :param rmod_link_protocol: type of rmod link protocol, can be "CPRI", "ECPRI_NETCONF" or "OBSAI"
        :type rmod_link_protocol: str
        :return: OranEcpriRmod, OranCpriRmod or OranObsaiRmod instance
        :rtype: Rmod
        """
        rmod_link_protocol = rmod_link_protocol.lower()
        if "ecpri" in rmod_link_protocol:
            return OranEcpriRmod()
        elif "cpri" in rmod_link_protocol:
            return OranCpriRmod()
        elif "obsai" in rmod_link_protocol:
            return OranObsaiRmod()
